package local.lito381.server;
import java.io.*;import java.util.*;import java.util.concurrent.locks.*;
/** Captured caster-centred membership, independent existing HP plans, shared immutable Context snapshot data. */
final class NativeAcceptedAreaFreezeMutation {
 static final class Group {
  final NativeAreaMaterialAction.Context c;final NativePlayerLifetime lifetime;final int cx,cy;final IdentityHashMap<ClientSession,NativeAcceptedFreezeMutation.Batch> targets=new IdentityHashMap<>();final List<Output> outputs=new ArrayList<>();final List<Npc> npcs=new ArrayList<>();final List<Player> pending=new ArrayList<>();NativeAcceptedFreezeMutation.Batch active;Output outbound;
  Group(NativeAreaMaterialAction.Context c,BattleSpellCatalog.FreezeAttackSpell spell,boolean world){this.c=c;cx=NativeAcceptedFreezeMutation.number(c.pc,"positionX");cy=NativeAcceptedFreezeMutation.number(c.pc,"positionY");lifetime=NativePlayerLifetime.of(c.hub);for(var pc:c.players)if(pc!=c.pc){var copy=new NativeAreaMaterialAction.Context(c);var b=new NativeAcceptedFreezeMutation.Batch(copy,pc,spell,world);CombatAccess.set(copy,NativeAcceptedFreezeMutation.FIELD,b);targets.put(pc,b);}}
  boolean scene(){return c.scene()&&NativeAcceptedFreezeMutation.number(c.pc,"positionX")==cx&&NativeAcceptedFreezeMutation.number(c.pc,"positionY")==cy;}
 }
 record Player(NativeAcceptedFreezeMutation.Batch batch,int amount,ClientSession caster,boolean flag){}
 record Npc(CombatWorldFreeze.Batch batch,ClientSession pc,ClassicWorldMonsterPopulation.Snapshot target,int amount){}
 record Output(ClientSession pc,NativePlayerCommit.Binding binding,byte[] packet,String note){}
 static Object raw(){var c=NativeAreaMaterialAction.current.get();return c==null?null:CombatAccess.field(c,NativeAcceptedFreezeMutation.FIELD);}
 static Group group(){return raw()instanceof Group g?g:null;}
 static NativeAcceptedFreezeMutation.Batch current(){var state=raw();return state instanceof Group g?g.active:NativeAcceptedFreezeMutation.nativeAreaFreezeOriginalCurrent();}
 static boolean captureOutput(ClientSession receiver,byte[] packet,String note){var g=group();if(g==null)return NativeAcceptedFreezeMutation.nativeAreaFreezeOriginalCaptureOutput(receiver,packet,note);if(g.outbound!=null)return false;var binding=g.c.bindings.get(receiver);if(binding!=null)g.outputs.add(new Output(receiver,binding,packet.clone(),note));return true;}
 static void battle(ClientSession pc,byte[] packet,BattleSpellCatalog.FreezeAttackSpell spell)throws IOException{run(pc,packet,spell,false);}
 static void world(ClientSession pc,byte[] packet,BattleSpellCatalog.FreezeAttackSpell spell)throws IOException{run(pc,packet,spell,true);}
 static void original(ClientSession pc,byte[] packet,BattleSpellCatalog.FreezeAttackSpell spell,boolean world)throws IOException{if(world)pc.nativeAreaFreezeOriginalWorld(packet,spell);else pc.nativeAreaFreezeOriginalBattle(packet,spell);}
 static void run(ClientSession pc,byte[] packet,BattleSpellCatalog.FreezeAttackSpell spell,boolean world)throws IOException {
  if(spell.skillId()!=80){original(pc,packet,spell,world);return;}var hub=(GameHub)CombatAccess.field(pc,"hub");if((boolean)CombatAccess.field(hub,"nativeStaticMotionClosed")||NativePlayerLifetime.of(hub).mode!=NativePlayerLifetime.Mode.OPEN)return;var c=new NativeAreaMaterialAction.Context(pc);if(!c.phase.equals(world?"WORLD":"BATTLE"))return;var g=new Group(c,spell,world);CombatAccess.set(c,NativeAcceptedFreezeMutation.FIELD,g);var locks=c.players.stream().map(ClientSession::nativePlayerActionLock).distinct().toList();int acquired=0;
  for(int attempt=0;attempt<32;attempt++){for(;acquired<locks.size();acquired++)if(!locks.get(acquired).tryLock())break;if(acquired==locks.size())break;while(acquired>0)locks.get(--acquired).unlock();if(Thread.currentThread().isInterrupted()||!c.caster.matches(pc))return;LockSupport.parkNanos(1_000_000L);}
  if(acquired!=locks.size())return;var scope=NativePlayerActionScope.enter(c.players.toArray(ClientSession[]::new));
  try{if(g.scene()&&NativePlayerLifetime.of(hub).mode==NativePlayerLifetime.Mode.OPEN)NativeAreaMaterialAction.owned(c,()->original(pc,packet,spell,world));}
  finally{while(acquired>0)locks.get(--acquired).unlock();for(var member:c.players)NativePlayerActionScope.unlocked(member);scope.close();try{emit(g);for(var p:g.pending)publish(p);for(var n:g.npcs)CombatWorldFreeze.enqueueBatch(n.batch,n.pc,n.target,n.amount);}finally{g.pending.clear();g.npcs.clear();for(var b:g.targets.values()){synchronized(b){b.producerDone=true;}NativeAcceptedFreezeMutation.finish(b);}g.outputs.clear();g.active=null;CombatAccess.set(c,NativeAcceptedFreezeMutation.FIELD,null);}}
 }
 static boolean enqueueBatch(CombatWorldFreeze.Batch batch,ClientSession pc,ClassicWorldMonsterPopulation.Snapshot target,int amount){var g=group();if(g==null)return CombatWorldFreeze.enqueueBatch(batch,pc,target,amount);if(batch==null||!((Map<?,?>)CombatAccess.field(batch,"targets")).containsKey(target.objectId()))return false;g.npcs.add(new Npc(batch,pc,target,amount));return true;}
 static NativeAcceptedFreezeMutation.Batch selected(ClientSession target){var g=group();if(g==null)return null;var b=g.targets.get(target);g.active=b;if(b!=null&&!b.valid(false))b.cancelled=true;return b;}
 static void damageBattle(ClientSession target,int amount,ClientSession caster){var g=group();var b=selected(target);if(g!=null&&(b==null||b.cancelled))return;if(b!=null){b.eligible=amount>0;if(b.eligible){g.pending.add(new Player(b,amount,caster,false));return;}}CombatPlayerDamage.battle(target,amount,caster);}
 static void damageWorld(ClientSession target,int amount,ClientSession caster,boolean flag){var g=group();var b=selected(target);if(g!=null&&(b==null||b.cancelled))return;if(b!=null){b.eligible=amount>0;if(b.eligible){g.pending.add(new Player(b,amount,caster,flag));return;}}CombatPlayerDamage.world(target,amount,caster,flag);}
 static boolean consume(BattleEraseMagicStatus status,BattleEraseMagicStatus.Lease lease){var g=group();var b=g==null?null:g.active;if(b!=null&&b.cancelled)return false;if(b==null||!b.eligible||CombatAccess.field(b.target,"eraseMagicStatus")!=status)return NativeAcceptedFreezeMutation.consume(status,lease);b.erase=lease;return false;}
 static boolean capture(BattleTimedStatus status,long now,int seconds,List<ClientSession> audience){var g=group();var b=g==null?null:g.active;if(b!=null&&b.cancelled)return false;if(b==null||!b.eligible||CombatAccess.field(b.target,"timedStatus")!=status)return NativeAcceptedFreezeMutation.capture(status,now,seconds,audience);b.freeze=true;b.seconds=seconds;b.audience=audience==null?null:List.copyOf(audience);return false;}
 static void publish(Player p){var b=p.batch;NativeSourcePlayerActionLock.runPairOrdered(b.c.pc,b.target,()->{if(!b.valid(false)||b.lifetime.mode==NativePlayerLifetime.Mode.STOPPED){b.cancelled=true;return;}try{NativeAreaMaterialAction.owned(b.c,()->{if(b.world)CombatPlayerDamage.world(b.target,p.amount,p.caster,p.flag);else CombatPlayerDamage.battle(b.target,p.amount,p.caster);});}catch(IOException e){throw new UncheckedIOException(e);}});}
 static List<ClientSession> players(List<ClientSession> values){var g=group();return g==null?values:values.stream().filter(g.c::player).toList();}
 static void replayBattle(ClientSession pc,BattleSpellCatalog.FreezeAttackSpell spell,ClientSession target,List<ClientSession> audience)throws IOException{if(spell.skillId()==80)pc.nativeAreaFreezeAcceptedBattle(spell,target,audience);else pc.nativeFreezeAcceptedBattle(spell,target,audience);}
 static void replayWorld(ClientSession pc,BattleSpellCatalog.FreezeAttackSpell spell,ClientSession target,List<ClientSession> audience)throws IOException{if(spell.skillId()==80)pc.nativeAreaFreezeAcceptedWorld(spell,target,audience);else pc.nativeFreezeAcceptedWorld(spell,target,audience);}
 static long id(byte[] p,int at){return Integer.toUnsignedLong((p[at]&255)|(p[at+1]&255)<<8|(p[at+2]&255)<<16|(p[at+3]&255)<<24);}
 static boolean fast(Group g,ClientSession pc){return NativeAcceptedFreezeMutation.roleFrame(g.c.bindings.get(pc),pc);}
 // The existing final native socket monitor must not acquire Source/Hub/status locks.
 static boolean allowFrame(ClientSession receiver,byte[] packet){var g=group();if(g==null||g.outbound==null)return true;var o=g.outbound;if(o.pc!=receiver||g.lifetime.mode==NativePlayerLifetime.Mode.STOPPED||(boolean)CombatAccess.field(g.c.hub,"nativeStaticMotionClosed")||!fast(g,g.c.pc)||!fast(g,receiver))return false;if(packet.length>=22&&(packet[0]&255)==Protocol.S_ATTACK_MANY){int count=(packet[20]&255)|(packet[21]&255)<<8;if(packet.length==22+count*5)for(int k=0;k<count;k++){long object=id(packet,22+k*5);for(var entry:g.targets.entrySet())if(g.c.bindings.get(entry.getKey()).object()==object){var b=entry.getValue();var state=CombatAccess.field(CombatAccess.field(b.target,"timedStatus"),"sourcePoisonLifecycle");Object epoch=b.frame!=null&&b.frame.accepted&&b.frame.fatal?b.deathLife:b.life;if(!fast(g,b.target)||state==null||CombatAccess.field(state,"sourceNpcOwner")!=epoch)return false;}}}return true;}
 static byte[] packet(Group g,byte[] original){if(original.length<22||(original[0]&255)!=Protocol.S_ATTACK_MANY)return original;int count=(original[20]&255)|(original[21]&255)<<8;if(original.length!=22+count*5)return original;var keep=new ArrayList<Integer>();for(int k=0;k<count;k++){int at=22+k*5;long id=id(original,at);var entry=g.targets.entrySet().stream().filter(e->g.c.bindings.get(e.getKey()).object()==id).findFirst().orElse(null);if(entry==null||g.c.player(entry.getKey())&&(entry.getValue().valid(false)||(int)CombatAccess.field(entry.getKey(),"playerHp")==0))keep.add(k);}if(keep.size()==count)return original;var out=Arrays.copyOf(original,22+keep.size()*5);out[20]=(byte)keep.size();out[21]=(byte)(keep.size()>>8);for(int k=0;k<keep.size();k++)System.arraycopy(original,22+keep.get(k)*5,out,22+k*5,5);return out;}
 static void emit(Group g){for(var o:g.outputs){Runnable[] out={null};NativeSourcePlayerActionLock.run(o.pc,()->{if(o.binding.matches(o.pc))out[0]=NativeRolePublication.completion(o.pc,()->{boolean valid;synchronized(g.c.hub){valid=o.binding.matches(o.pc)&&g.c.player(o.pc)&&g.scene()&&!(boolean)CombatAccess.field(g.c.hub,"nativeStaticMotionClosed")&&g.lifetime.mode!=NativePlayerLifetime.Mode.STOPPED;}if(valid)try{g.outbound=o;NativeAreaMaterialAction.owned(g.c,()->o.pc.nativeSelfOriginalSend(packet(g,o.packet),o.note));}catch(IOException e){throw new UncheckedIOException(e);}finally{g.outbound=null;}});});if(out[0]!=null)out[0].run();}}
 private NativeAcceptedAreaFreezeMutation(){}
}
